'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHTML = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => globalThis.crypto?.randomUUID?.() || Date.now().toString(36)+Math.random().toString(36).slice(2);
const today = () => {const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel = value => value ? new Date(value+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'}) : 'No date';
const paths={home:'index',planner:'planner',atlas:'atlas',library:'library',lab:'lab',focus:'focus',insights:'insights',settings:'settings'};
const labels={home:'Overview',planner:'Project board',atlas:'Discovery atlas',library:'Notebook',lab:'Creative lab',focus:'Focus room',insights:'Your insights',settings:'Preferences'};
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',planner:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M15 4v16"/>',atlas:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',library:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4zm16 0h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z"/>',lab:'<path d="M9 3h6M10 3v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10"/>',focus:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3"/>',insights:'<path d="M4 20h17M6 16v-4m6 4V5m6 11V9"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m8 4 12 8-12 8z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M4 9a8 8 0 1 1 0 6M4 3v6h6"/>',trash:'<path d="M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.home}</svg>`;
const initial = () => ({version:1,profile:{name:'Explorer',theme:'light',motion:true},tasks:[{id:'t1',title:'Sketch a new possibility',description:'Give that idea in the back of your mind a little space.',category:'Creative',priority:'High',status:'active',date:today()},{id:'t2',title:'Collect three sparks of inspiration',description:'A place, a color, a sentence. Follow your curiosity.',category:'Discovery',priority:'Normal',status:'todo',date:today()},{id:'t3',title:'Make time for deep work',description:'One quiet session. One meaningful thing.',category:'Personal',priority:'Normal',status:'todo',date:today()},{id:'t4',title:'Build an inspiration notebook',description:'A home for all the things worth keeping.',category:'Creative',priority:'Normal',status:'done',date:today(),completedAt:new Date().toISOString()},{id:'t5',title:'Explore the generative lab',description:'See what happens when structure meets a little chaos.',category:'Creative',priority:'Low',status:'active',date:''}],notes:[{id:'n1',title:'A field guide to getting started',tag:'Guide',body:'# Welcome to your orbit\n\nThis is a little universe for the things you want to make, learn, and explore.\n\n## Follow a spark\n- Visit the Discovery atlas and save a place that speaks to you.\n- Turn it into a project on your board.\n- Open the focus room and give it your full attention.\n\n## Make it yours\nEverything you write stays in this browser. Export a backup in Preferences whenever you like.\n\nSmall steps have a way of becoming big things.',updatedAt:new Date().toISOString()},{id:'n2',title:'Things I want to make',tag:'Ideas',body:'# A collection of possibilities\n\n- A poster inspired by an imaginary landscape\n- A tiny ritual that makes every day better\n- Something beautiful from a happy accident\n\n**Start before you feel ready.**',updatedAt:new Date().toISOString()},{id:'n3',title:'Notes from the quiet hours',tag:'Reflection',body:'# Leave a little room\n\nThe best ideas often arrive when there is nothing competing for your attention.\n\nWhat would you discover if you slowed down for twenty-five minutes?',updatedAt:new Date().toISOString()}],saved:[],sessions:[],activity:[{text:'Your creative workspace is ready',time:new Date().toISOString()}],timer:{mode:'focus',duration:1500,remaining:1500,end:null,running:false},lab:{pattern:'flow',density:80,speed:30,scale:50,palette:0,seed:42},onboarded:false});
let storageOK=true,state;
try{state=JSON.parse(localStorage.getItem('orbit-workspace-v1'))||initial();if(state.version!==1||!Array.isArray(state.tasks)||!Array.isArray(state.notes))state=initial();}catch{state=initial();storageOK=false;}
const page=document.body.dataset.page||'home';
function save(){try{localStorage.setItem('orbit-workspace-v1',JSON.stringify(state));}catch{storageOK=false;toast('Browser storage is unavailable. Export a backup to keep your work.');}}
function activity(text){state.activity.unshift({text,time:new Date().toISOString()});state.activity=state.activity.slice(0,30);save();}
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function applyPreferences(){document.documentElement.dataset.theme=state.profile.theme;document.documentElement.classList.toggle('no-motion',!state.profile.motion);}
applyPreferences();
function shell(){document.body.innerHTML=`<a class="skip" href="#main">Skip to content</a><div class="mobile-overlay" id="navOverlay"></div><aside class="sidebar" id="sidebar"><a class="brand" href="index.html" aria-label="Orbit overview"><span class="brand-mark"></span>ORBIT</a><div class="workspace"><span class="avatar">${escapeHTML(state.profile.name.slice(0,2).toUpperCase())}</span><div><strong style="font-size:12px">Personal workspace</strong><div class="muted" style="font-size:10px">A little space for big ideas</div></div></div><div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${Object.keys(paths).filter(k=>k!=='settings').map(k=>`<a href="${paths[k]}.html" ${page===k?'class="active" aria-current="page"':''}>${icon(k)}${labels[k]}${k==='planner'?`<span class="count">${state.tasks.filter(t=>t.status!=='done').length}</span>`:''}</a>`).join('')}</nav></div><div class="side-bottom"><div class="side-note"><span class="eyebrow muted">A MOMENT OF SPACE</span><p>Good things begin with a little uninterrupted time.</p><a class="btn small" href="focus.html">Find your focus ${icon('arrow')}</a></div><nav class="nav" aria-label="Workspace settings"><a href="settings.html" ${page==='settings'?'class="active" aria-current="page"':''}>${icon('settings')}Preferences</a><a href="#" id="helpLink">${icon('info')}A quick introduction</a></nav><div class="status"><span class="dot" style="background:#8ca868"></span>${storageOK?'Saved on this device':'Temporary session'}</div></div></aside><header class="topbar"><button class="btn ghost iconbtn mobile-menu" id="menuButton" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumbs">Workspace <span>/ &nbsp; ${labels[page]}</span></div><button class="btn search-trigger" id="searchButton"><span class="row">${icon('search')}Search your orbit</span><span class="key">Ctrl K</span></button><button class="btn ghost iconbtn" id="themeButton" aria-label="Toggle light or dark theme">${icon('moon')}</button><span class="avatar" title="${escapeHTML(state.profile.name)}">${escapeHTML(state.profile.name.slice(0,2).toUpperCase())}</span></header><main class="main" id="main" tabindex="-1"><div id="content"></div><footer class="footer"><span>ORBIT / A SPACE FOR POSSIBILITY</span><span>Made for curiosity. &nbsp; <a href="settings.html">Your data, your device ↗</a></span></footer></main><dialog class="modal" id="modal"></dialog><dialog class="modal search-modal" id="searchModal" aria-label="Search your workspace"><label class="screenreader" for="globalSearch">Search pages, projects, and notes</label><input id="globalSearch" placeholder="Where would you like to go?" autocomplete="off"><div class="search-results" id="searchResults"></div><div class="search-foot">Pages, projects & notes &nbsp; · &nbsp; Esc to close</div></dialog><div class="toast-container" id="toasts" role="status" aria-live="polite"></div>`;$('#menuButton').onclick=()=>{const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#navOverlay').classList.toggle('open',open);$('#menuButton').setAttribute('aria-expanded',open);};$('#navOverlay').onclick=()=>{$('#sidebar').classList.remove('open');$('#navOverlay').classList.remove('open');$('#menuButton').setAttribute('aria-expanded','false');};$('#themeButton').onclick=()=>{state.profile.theme=state.profile.theme==='light'?'dark':'light';applyPreferences();save();if(page==='settings')renderSettings();};$('#helpLink').onclick=e=>{e.preventDefault();showWelcome();};$('#searchButton').onclick=openSearch;$('#globalSearch').oninput=renderSearch;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));}
function head(eyebrow,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function modal(title,body,actions=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modalTitle">${title}</h2><button class="btn ghost iconbtn" id="closeModal" aria-label="Close dialog">${icon('close')}</button></div>${body}${actions}`;d.setAttribute('aria-labelledby','modalTitle');$('#closeModal').onclick=()=>d.close();if(!d.open)d.showModal();return d;}
function showWelcome(){modal('Welcome to your orbit.',`<div class="stack"><p class="muted">An interconnected space for ideas, curiosity, and the things you want to make.</p><div class="help-grid">${[['planner','Make a plan','Create projects and move them from an idea to done.'],['atlas','Follow your curiosity','Explore six imaginary worlds and collect inspiration.'],['library','Keep the good bits','Write, search, and preview your own notes.'],['lab','Make something beautiful','Shape an animated artwork and export it.'],['focus','Find your quiet','Use a focus timer with optional ambient sound.'],['insights','See your momentum','Understand your actual progress over time.']].map(([k,t,p])=>`<a class="feature-card" href="${paths[k]}.html"><div>${icon(k)}<h3>${t}</h3><p>${p}</p></div></a>`).join('')}</div><div class="info-strip">${icon('info')}Includes starter projects and notes. Your work is saved in this browser; use Preferences to export a backup.</div><button class="btn primary" id="welcomeDone">Let’s explore ${icon('arrow')}</button></div>`);$('#welcomeDone').onclick=()=>{state.onboarded=true;save();$('#modal').close();};}
function openSearch(){renderSearch();$('#searchModal').showModal();$('#globalSearch').focus();}
function renderSearch(){const q=$('#globalSearch').value.toLowerCase().trim();const all=[...Object.keys(paths).map(k=>({title:labels[k],subtitle:'Workspace page',href:paths[k]+'.html',type:k})),...state.tasks.map(t=>({title:t.title,subtitle:'Project · '+t.category,href:'planner.html?task='+encodeURIComponent(t.id),type:'planner'})),...state.notes.map(n=>({title:n.title,subtitle:'Note · '+n.tag,href:'library.html?note='+encodeURIComponent(n.id),type:'library'}))];const matches=all.filter(i=>(i.title+' '+i.subtitle).toLowerCase().includes(q)).slice(0,12);$('#searchResults').innerHTML=matches.length?matches.map(i=>`<a class="search-result" href="${i.href}">${icon(i.type)}<div><div>${escapeHTML(i.title)}</div><small>${escapeHTML(i.subtitle)}</small></div><span class="spacer"></span>${icon('arrow')}</a>`).join(''):'<div class="empty">Nothing found. Try another word.</div>';}
function orbitArt(){return `<svg class="orbit-art" viewBox="0 0 520 330" role="img" aria-label="An abstract solar system of ideas"><defs><radialGradient id="sphere"><stop stop-color="#faf8de" offset="0"/><stop stop-color="#b7c784" offset=".55"/><stop stop-color="#728559" offset="1"/></radialGradient><radialGradient id="smallSphere"><stop stop-color="#f5b09b"/><stop offset="1" stop-color="#b8563e"/></radialGradient><filter id="blur"><feGaussianBlur stdDeviation="12"/></filter></defs><ellipse cx="260" cy="265" rx="90" ry="16" fill="#6a7654" opacity=".13" filter="url(#blur)"/><g fill="none" stroke="#a1ab8d" stroke-width=".7"><ellipse cx="260" cy="165" rx="210" ry="64" transform="rotate(-25 260 165)"/><ellipse cx="260" cy="165" rx="156" ry="97" transform="rotate(36 260 165)"/><circle cx="260" cy="165" r="126" stroke-dasharray="2 6" opacity=".55"/><path d="M30 165h460M260 20v290" stroke-dasharray="2 7" opacity=".4"/></g><g class="orbital-spin"><circle cx="75" cy="215" r="18" fill="url(#smallSphere)"/><circle cx="438" cy="122" r="6" fill="#525d43"/></g><g class="orbital-spin reverse"><circle cx="318" cy="50" r="13" fill="#dfd4e9" stroke="#bdb1ca"/><circle cx="203" cy="279" r="4" fill="#d55d41"/></g><circle cx="260" cy="165" r="73" fill="url(#sphere)"/><g fill="none" stroke="#e8edc9" stroke-width=".7" opacity=".6"><ellipse cx="260" cy="165" rx="73" ry="24" transform="rotate(-20 260 165)"/><ellipse cx="260" cy="165" rx="73" ry="46" transform="rotate(-20 260 165)"/><ellipse cx="260" cy="165" rx="27" ry="73" transform="rotate(-20 260 165)"/><ellipse cx="260" cy="165" rx="51" ry="73" transform="rotate(-20 260 165)"/></g><g fill="#626d52" font-size="8" font-family="monospace"><text x="41" y="58">EVERY IDEA HAS AN ORBIT</text><text x="410" y="280">∞ POSSIBILITY</text></g><g stroke="#899676" stroke-width=".8"><path d="M40 40v8m-4-4h8M445 250v8m-4-4h8M390 65v8m-4-4h8"/></g></svg>`;}
function taskLine(t){return `<div class="task-line ${t.status==='done'?'done':''}"><button class="check" data-complete="${t.id}" aria-label="${t.status==='done'?'Reopen':'Complete'} ${escapeHTML(t.title)}">${t.status==='done'?'✓':''}</button><div class="spacer"><a href="planner.html?task=${encodeURIComponent(t.id)}" class="task-title">${escapeHTML(t.title)}</a><div><small>${escapeHTML(t.category)} · ${dateLabel(t.date)}</small></div></div><span class="pill ${t.priority==='High'?'coral':''}">${t.priority}</span></div>`;}
function completeTask(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;t.status=t.status==='done'?'todo':'done';t.completedAt=t.status==='done'?new Date().toISOString():null;activity(`${t.status==='done'?'Completed':'Reopened'} “${t.title}”`);toast(t.status==='done'?'A little more momentum. Project complete.':'Project reopened.');}
function bindChecks(refresh){$$('[data-complete]').forEach(b=>b.onclick=()=>{completeTask(b.dataset.complete);refresh();});}
function renderHome(){const done=state.tasks.filter(t=>t.status==='done').length;const minutes=state.sessions.reduce((a,s)=>a+s.minutes,0);const hour=new Date().getHours();$('#content').innerHTML=head('YOUR PERSONAL COMMAND CENTER',`Good ${hour<12?'morning':hour<18?'afternoon':'evening'}, ${escapeHTML(state.profile.name)}.`,`A little clarity. A little curiosity. A whole world of possibility.`,`<button class="btn primary" id="quickAdd">${icon('plus')}New project</button>`)+`<div class="stack"><div class="hero"><div class="hero-copy"><span class="eyebrow" style="color:#697557">SPACE TO THINK. ROOM TO GROW.</span><h2>Small ideas.<br>Extraordinary orbits.</h2><p>Gather what inspires you. Make a little progress. Give your next big thing the space it deserves.</p><a href="atlas.html" class="btn primary">Explore your universe ${icon('arrow')}</a></div><div class="hero-art">${orbitArt()}<span class="art-label">FIG. 01 / POSSIBILITY IN MOTION</span></div></div><div class="grid four">${[[icon('planner'),'Projects in motion',state.tasks.filter(t=>t.status==='active').length,'One step at a time', 'lime'],[icon('focus'),'Time well spent',minutes+' <small>min</small>','Completed focus sessions','purple'],[icon('library'),'Ideas collected',state.notes.length,'A growing constellation','blue'],[icon('check'),'Projects complete',done,`${state.tasks.length?Math.round(done/state.tasks.length*100):0}% of your current board`,'coral']].map(([i,t,v,s])=>`<div class="panel stat"><div class="stat-top"><span>${t}</span>${i}</div><div class="number">${v}</div><div class="row between"><small class="muted">${s}</small><div class="mini-bars">${[9,16,12,22,18,25].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div></div>`).join('')}</div><div class="grid two"><section class="panel"><div class="panel-head"><h2>A little forward motion</h2><a class="learn-link" href="planner.html">View board ↗</a></div>${state.tasks.filter(t=>t.status!=='done').slice(0,4).map(taskLine).join('')||'<div class="empty">All clear. Make space for your next idea.</div>'}<div style="margin-top:20px" class="row between"><small class="muted">${done} of ${state.tasks.length} projects complete</small><small class="muted">Keep going.</small></div><div class="progress" style="margin-top:10px"><div style="width:${state.tasks.length?done/state.tasks.length*100:0}%"></div></div></section><section class="panel"><div class="panel-head"><h2>Follow a spark</h2><span class="pill">START SOMEWHERE</span></div><div class="stack"><a class="feature-card" href="lab.html"><div class="feature-symbol">✳</div><div class="spacer"><h3>A beautiful accident</h3><small class="muted">Play with the generative art lab</small></div>${icon('arrow')}</a><a class="feature-card" href="library.html"><div class="feature-symbol" style="background:var(--lime)">✎</div><div class="spacer"><h3>Catch a passing thought</h3><small class="muted">Your next idea belongs here</small></div>${icon('arrow')}</a></div></section></div><div class="grid two"><section class="panel"><div class="panel-head"><h2>Around your orbit</h2><span class="eyebrow muted">RECENT ACTIVITY</span></div><div class="activity">${state.activity.slice(0,3).map(a=>`<div class="activity-item"><span class="activity-icon">${icon('check')}</span><div><div>${escapeHTML(a.text)}</div><small class="muted">${new Date(a.time).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></div></div>`).join('')}</div></section><section class="panel" style="background:var(--purple);color:#3e324d"><span class="eyebrow">A THOUGHT TO TAKE WITH YOU</span><p class="quote">“Leave enough room in your day for something unexpected.”</p><span style="font-size:11px">A note from the ORBIT field guide</span></section></div></div>`;$('#quickAdd').onclick=()=>editTask();bindChecks(renderHome);}
let boardView='board',boardFilter='all',boardQuery='';
function renderPlanner(){const filtered=state.tasks.filter(t=>(boardFilter==='all'||t.category===boardFilter)&&(t.title+' '+t.description).toLowerCase().includes(boardQuery));$('#content').innerHTML=head('MAKE ROOM FOR WHAT MATTERS','From spark to something real.','A calm place to organize the things you’re moving toward.',`<button class="btn primary" id="addTask">${icon('plus')}New project</button>`)+`<div class="toolbar"><div class="segmented"><button data-view="board" class="${boardView==='board'?'active':''}">Board</button><button data-view="timeline" class="${boardView==='timeline'?'active':''}">Timeline</button></div><label class="screenreader" for="boardSearch">Filter projects</label><input id="boardSearch" type="search" placeholder="Find a project…" value="${escapeHTML(boardQuery)}"><label class="screenreader" for="boardFilter">Project category</label><select id="boardFilter" style="width:145px">${['all','Creative','Discovery','Personal'].map(c=>`<option value="${c}" ${boardFilter===c?'selected':''}>${c==='all'?'All categories':c}</option>`).join('')}</select><span class="spacer"></span><span class="muted" style="font-size:11px">${filtered.length} projects · saved automatically</span></div>${boardView==='board'?`<div class="board">${[['todo','On the horizon','○'],['active','In orbit','◉'],['done','Landed','✓']].map(([status,title,symbol])=>`<section class="column" data-status="${status}" aria-label="${title}"><div class="column-head"><strong>${symbol} &nbsp; ${title}</strong><span>${filtered.filter(t=>t.status===status).length}</span></div>${filtered.filter(t=>t.status===status).map(t=>`<article class="task-card" draggable="true" data-task="${t.id}"><div class="row between"><span class="pill ${t.category==='Creative'?'purple':t.category==='Discovery'?'lime':''}">${escapeHTML(t.category)}</span><button class="btn ghost small edit-task" data-edit="${t.id}" aria-label="Edit ${escapeHTML(t.title)}">Edit ↗</button></div><h3>${escapeHTML(t.title)}</h3><p>${escapeHTML(t.description)}</p><div class="row between"><small class="muted">${dateLabel(t.date)} ${t.priority==='High'?'· High priority':''}</small><select data-move="${t.id}" aria-label="Status of ${escapeHTML(t.title)}">${[['todo','On the horizon'],['active','In orbit'],['done','Landed']].map(([s,l])=>`<option value="${s}" ${t.status===s?'selected':''}>${l}</option>`).join('')}</select></div></article>`).join('')||'<div class="empty">Room for something new.</div>'}<button class="btn ghost small" data-add="${status}">${icon('plus')}Add a project</button></section>`).join('')}</div>`:`<section class="panel">${[...new Set(filtered.map(t=>t.date))].sort((a,b)=>a?b?a.localeCompare(b):-1:1).map(date=>`<div class="timeline-day"><strong style="font-size:12px">${dateLabel(date)}</strong><div class="timeline-tasks">${filtered.filter(t=>t.date===date).map(t=>`<button class="btn timeline-chip" data-edit="${t.id}">${t.status==='done'?'✓':t.status==='active'?'◉':'○'} ${escapeHTML(t.title)}</button>`).join('')}</div></div>`).join('')||'<div class="empty">No projects match your filters.</div>'}</section>`}<div class="info-strip" style="margin-top:22px">${icon('info')}Drag projects between columns, or use each card’s status menu. Select Edit to change the details.</div>`;$('#addTask').onclick=()=>editTask();$$('[data-add]').forEach(b=>b.onclick=()=>editTask(null,b.dataset.add));$$('[data-view]').forEach(b=>b.onclick=()=>{boardView=b.dataset.view;renderPlanner();});$('#boardFilter').onchange=e=>{boardFilter=e.target.value;renderPlanner();};$('#boardSearch').oninput=e=>{const pos=e.target.selectionStart;boardQuery=e.target.value.toLowerCase();renderPlanner();$('#boardSearch').focus();$('#boardSearch').setSelectionRange(pos,pos);};$$('[data-edit]').forEach(b=>b.onclick=()=>editTask(b.dataset.edit));$$('[data-move]').forEach(s=>s.onchange=()=>moveTask(s.dataset.move,s.value));$$('[draggable]').forEach(c=>c.ondragstart=e=>{e.dataTransfer.setData('text/plain',c.dataset.task);e.dataTransfer.effectAllowed='move';});$$('.column').forEach(c=>{c.ondragover=e=>{e.preventDefault();c.classList.add('drag-over');};c.ondragleave=()=>c.classList.remove('drag-over');c.ondrop=e=>{e.preventDefault();c.classList.remove('drag-over');const id=e.dataTransfer.getData('text/plain');if(state.tasks.some(t=>t.id===id))moveTask(id,c.dataset.status);};});}
function moveTask(id,status){const t=state.tasks.find(t=>t.id===id);const prev=t.status;t.status=status;if(status==='done'&&prev!=='done')t.completedAt=new Date().toISOString();else if(status!=='done')t.completedAt=null;activity(`Moved “${t.title}” to ${status==='done'?'Landed':status==='active'?'In orbit':'On the horizon'}`);renderPlanner();}
function editTask(id,status='todo',prefill={}){const existing=state.tasks.find(t=>t.id===id);const t=existing||{title:'',description:'',category:'Creative',priority:'Normal',date:today(),status,...prefill};modal(existing?'A little refinement.':'Start with a spark.',`<form id="taskForm"><div class="field"><label for="taskTitle">Project name</label><input id="taskTitle" required maxlength="120" value="${escapeHTML(t.title)}" placeholder="What would you like to make happen?"></div><div class="field"><label for="taskDescription">A little context</label><textarea id="taskDescription" maxlength="1500" placeholder="A next step, a small goal, a wild idea…">${escapeHTML(t.description)}</textarea></div><div class="grid two"><div class="field"><label for="taskCategory">Category</label><select id="taskCategory">${['Creative','Discovery','Personal'].map(c=>`<option ${t.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="taskPriority">Priority</label><select id="taskPriority">${['Low','Normal','High'].map(c=>`<option ${t.priority===c?'selected':''}>${c}</option>`).join('')}</select></div></div><div class="field"><label for="taskDate">Target date (optional)</label><input id="taskDate" type="date" value="${escapeHTML(t.date)}"></div><div class="modal-actions">${existing?`<button class="btn" type="button" id="deleteTask">${icon('trash')}Delete</button>`:''}<button class="btn primary" type="submit">${existing?'Save changes':'Create project'} ${icon('arrow')}</button></div></form>`);$('#taskForm').onsubmit=e=>{e.preventDefault();const title=$('#taskTitle').value.trim();if(!title){$('#taskTitle').setCustomValidity('Give this project a name.');$('#taskTitle').reportValidity();return;}const data={title,description:$('#taskDescription').value.trim(),category:$('#taskCategory').value,priority:$('#taskPriority').value,date:$('#taskDate').value};if(existing)Object.assign(existing,data);else state.tasks.unshift({id:uid(),status,...data});activity(`${existing?'Updated':'Created'} “${data.title}”`);$('#modal').close();if(page==='home')renderHome();if(page==='planner')renderPlanner();toast(existing?'Project updated.':'A new idea is in your orbit.');};$('#taskTitle').oninput=e=>e.target.setCustomValidity('');if(existing)$('#deleteTask').onclick=()=>{modal('Delete this project?',`<p class="muted">“${escapeHTML(existing.title)}” will be removed from your board.</p>`,`<div class="modal-actions"><button class="btn" id="cancelDelete">Keep it</button><button class="btn accent" id="confirmDelete">Delete project</button></div>`);$('#cancelDelete').onclick=()=>editTask(id);$('#confirmDelete').onclick=()=>{state.tasks=state.tasks.filter(t=>t.id!==id);activity('Removed a project from the board');$('#modal').close();if(page==='planner')renderPlanner();else if(page==='home')renderHome();};};}
const destinations=[{id:'d1',title:'The Glass Archipelago',region:'Oceanic',color:'#668f90',accent:'#cadbc2',mood:'Wonder',subtitle:'Where the sea learns to hold the light.',body:'Imagine an archipelago made of translucent stone. At dawn, every island catches a different color. Bridges hum softly in the wind, and the tide moves in the shadows beneath your feet.',prompt:'Make a color palette from a sunrise you have never seen. What would a transparent city feel like?',minutes:12},{id:'d2',title:'The Amber Dunes',region:'Desert',color:'#ba7451',accent:'#efc494',mood:'Stillness',subtitle:'A thousand quiet miles, one clear thought.',body:'A landscape of soft-edged dunes and suspended circles of stone. Nothing here hurries. The sun is a copper coin, and the only path is the one you make.',prompt:'Sketch a landscape using only three curved lines. Let the empty space do most of the work.',minutes:8},{id:'d3',title:'The Violet Observatory',region:'Cosmic',color:'#695d84',accent:'#d0b6dd',mood:'Wonder',subtitle:'A window into what might be.',body:'High above a violet planet, an observatory maps stars that have not been born yet. Its circular rooms rotate slowly. Every telescope reveals a different possible future.',prompt:'Write a postcard from yourself ten years in the future. Describe an ordinary day that makes you happy.',minutes:15},{id:'d4',title:'The Moss Cathedral',region:'Forest',color:'#507060',accent:'#b9c78e',mood:'Stillness',subtitle:'A sanctuary built by time.',body:'In the oldest forest, trees curve into an enormous living dome. Light arrives in thin gold columns. A moss garden remembers every footstep and gently grows over it.',prompt:'Design a small daily ritual inspired by the forest. Think about what to keep, and what to let grow away.',minutes:10},{id:'d5',title:'The Floating Quarter',region:'Urban',color:'#657e95',accent:'#c6d7dc',mood:'Energy',subtitle:'A city with room to dream.',body:'Above an ordinary city floats an extraordinary neighborhood. Its blocks drift like clouds, meeting in new configurations. Every rooftop is a public garden and every elevator has a view.',prompt:'Invent a public space that your neighborhood is missing. What would bring people together there?',minutes:18},{id:'d6',title:'The Vermilion Gardens',region:'Desert',color:'#a95b54',accent:'#eab5a1',mood:'Energy',subtitle:'An unexpected bloom at the edge of everything.',body:'Beyond a red-rock canyon, a garden grows in geometric terraces. Plants bloom in precise rhythms. Water traces circles through the stone, and the whole place feels like a living instrument.',prompt:'Create a repeating pattern from a leaf, a circle, and a line. Bring it to life in the Creative lab.',minutes:10}];
function landscape(d,big=false){const idx=destinations.indexOf(d);const mountain=idx%3===0?'<path d="M0 165 65 110 108 150 175 65 240 140 300 80 400 150V240H0z" fill="#203f43" opacity=".5"/><path d="M0 205 80 175 160 196 225 157 330 183 400 160v80H0z" fill="#173e40" opacity=".6"/>':idx%3===1?'<path d="M0 170Q90 95 185 180T400 145v95H0z" fill="#7b4138" opacity=".45"/><path d="M0 215Q140 155 280 210T400 200v40H0z" fill="#713c36" opacity=".55"/>':'<path d="M65 210v-70h48v70m30 0V95h48v115m30 0v-45h55v45m25 0V120h45v90" fill="#2c354d" opacity=".65"/><ellipse cx="198" cy="212" rx="140" ry="10" fill="#1b293e" opacity=".4"/>';return `<div class="landscape" style="--scene:${d.color};${big?'height:240px':''}"><span class="scene-no">0${idx+1} / IMAGINED WORLDS</span><svg viewBox="0 0 400 240" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Abstract illustration of ${d.title}"><defs><linearGradient id="sky${d.id}" x2="0" y2="1"><stop stop-color="${d.color}"/><stop offset="1" stop-color="${d.accent}"/></linearGradient></defs><rect width="400" height="240" fill="url(#sky${d.id})"/><circle cx="${260-idx*10}" cy="${90+idx*2}" r="${36+idx*3}" fill="${d.accent}" opacity=".8"/><circle cx="${260-idx*10}" cy="${90+idx*2}" r="${49+idx*3}" fill="none" stroke="${d.accent}" stroke-width=".5"/>${mountain}<g fill="none" stroke="${d.accent}" stroke-width=".6" opacity=".5">${Array.from({length:7},(_,i)=>`<path d="M0 ${210+i*5}Q200 ${170+i*6} 400 ${210+i*5}"/>`).join('')}</g><g fill="${d.accent}" opacity=".6"><circle cx="50" cy="55" r="1"/><circle cx="130" cy="82" r="1"/><circle cx="355" cy="43" r="1.5"/></g></svg><span class="scene-tag">${d.region.toUpperCase()} / ${d.mood.toUpperCase()}</span></div>`;}
let atlasFilter='All',atlasQuery='';
function renderAtlas(){const list=destinations.filter(d=>(atlasFilter==='All'||(atlasFilter==='Saved'?state.saved.includes(d.id):d.mood===atlasFilter))&&(d.title+' '+d.region).toLowerCase().includes(atlasQuery));$('#content').innerHTML=head('GO SOMEWHERE UNEXPECTED','A world beyond the ordinary.','Six imagined places. Six invitations to think a little differently.',`<span class="pill lime">${state.saved.length} places in your collection</span>`)+`<div class="toolbar"><div class="segmented">${['All','Wonder','Stillness','Energy','Saved'].map(s=>`<button class="${s===atlasFilter?'active':''}" data-atlasfilter="${s}">${s}</button>`).join('')}</div><span class="spacer"></span><label class="screenreader" for="atlasSearch">Find a world</label><input id="atlasSearch" type="search" value="${escapeHTML(atlasQuery)}" placeholder="Find a world…"></div><div class="atlas-grid">${list.map(d=>`<article class="destination"><button class="save-destination ${state.saved.includes(d.id)?'saved':''}" data-save="${d.id}" aria-pressed="${state.saved.includes(d.id)}" aria-label="Save ${d.title}">${icon('star')}</button>${landscape(d)}<div class="destination-copy"><span class="eyebrow muted">${d.region} / 0${destinations.indexOf(d)+1}</span><h3>${d.title}</h3><p>${d.subtitle}</p><div class="row between"><span class="pill">${d.minutes} MIN CREATIVE DETOUR</span><button class="btn ghost small" data-discover="${d.id}" aria-label="Explore ${d.title}">Explore ${icon('arrow')}</button></div></div></article>`).join('')||'<div class="empty">No worlds here yet. Save a place that catches your eye.</div>'}</div><div class="info-strip" style="margin-top:24px">${icon('info')}These are fictional worlds designed as creative prompts. Save a favorite, then turn its invitation into a real project.</div>`;$$('[data-atlasfilter]').forEach(b=>b.onclick=()=>{atlasFilter=b.dataset.atlasfilter;renderAtlas();});$('#atlasSearch').oninput=e=>{const pos=e.target.selectionStart;atlasQuery=e.target.value.toLowerCase();renderAtlas();$('#atlasSearch').focus();$('#atlasSearch').setSelectionRange(pos,pos);};$$('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;const saved=state.saved.includes(id);state.saved=saved?state.saved.filter(s=>s!==id):[...state.saved,id];activity(`${saved?'Released':'Saved'} ${destinations.find(d=>d.id===id).title}`);renderAtlas();toast(saved?'Place removed from your collection.':'A new world in your collection.');});$$('[data-discover]').forEach(b=>b.onclick=()=>discover(b.dataset.discover));}
function discover(id){const d=destinations.find(d=>d.id===id);modal(d.title,`${landscape(d,true)}<p style="margin:20px 0" class="muted">${d.body}</p><div class="panel" style="background:var(--soft);padding:18px"><span class="eyebrow muted">YOUR CREATIVE INVITATION</span><p style="margin-top:10px">${d.prompt}</p></div>`,`<div class="modal-actions"><button class="btn" id="capturePrompt">${icon('library')}Keep as a note</button><button class="btn primary" id="startPrompt">${icon('plus')}Make it a project</button></div>`);$('#startPrompt').onclick=()=>editTask(null,'todo',{title:'Explore '+d.title,description:d.prompt,category:'Discovery'});$('#capturePrompt').onclick=()=>{const id=uid();state.notes.unshift({id,title:d.title+' · Field notes',tag:'Discovery',body:`# ${d.title}\n\n${d.body}\n\n## Creative invitation\n${d.prompt}\n\n## My thoughts\n`,updatedAt:new Date().toISOString()});activity('Captured a prompt from '+d.title);location.href='library.html?note='+encodeURIComponent(id);};}
let selectedNote=new URLSearchParams(location.search).get('note')||state.notes[0]?.id,noteQuery='',preview=false,noteSaveTimeout;
function markdown(text){return text.split('\n').map(line=>{let safe=escapeHTML(line);safe=safe.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>');if(line.startsWith('### '))return `<h3>${safe.slice(4)}</h3>`;if(line.startsWith('## '))return `<h2>${safe.slice(3)}</h2>`;if(line.startsWith('# '))return `<h1>${safe.slice(2)}</h1>`;if(line.startsWith('- '))return `<p style="padding-left:18px">• ${safe.slice(2)}</p>`;return `<p>${safe||'&nbsp;'}</p>`;}).join('');}
function renderLibrary(){let note=state.notes.find(n=>n.id===selectedNote);if(!note){selectedNote=state.notes[0]?.id;note=state.notes[0];}const list=state.notes.filter(n=>(n.title+' '+n.body+' '+n.tag).toLowerCase().includes(noteQuery));$('#content').innerHTML=head('YOUR GROWING CONSTELLATION','Keep what catches your mind.','A quiet home for ideas, field notes, and unfinished thoughts.',`<button class="btn primary" id="addNote">${icon('plus')}New note</button>`)+`<div class="notebook"><aside class="panel note-list" aria-label="Your notes"><div class="note-search"><label for="noteSearch" class="screenreader">Search notes</label><input id="noteSearch" type="search" placeholder="Search your notes…" value="${escapeHTML(noteQuery)}"></div>${list.map(n=>`<button class="note-item ${n.id===selectedNote?'active':''}" data-note="${n.id}" aria-pressed="${n.id===selectedNote}"><strong>${escapeHTML(n.title||'Untitled note')}</strong><small>${escapeHTML(n.tag)} · ${new Date(n.updatedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</small><small>${escapeHTML(n.body.replace(/[#*]/g,'').slice(0,65))}…</small></button>`).join('')||'<div class="empty">No matching notes.</div>'}</aside><section class="panel">${note?`<div class="row between wrap"><div class="row"><label for="noteTag" class="screenreader">Note tag</label><input id="noteTag" value="${escapeHTML(note.tag)}" maxlength="30" style="width:125px;padding:5px 8px;font-size:11px"><span class="muted" id="noteStatus" style="font-size:10px">Saved on this device</span></div><div class="row"><div class="segmented"><button data-editor="write" class="${!preview?'active':''}">Write</button><button data-editor="preview" class="${preview?'active':''}">Preview</button></div><button class="btn ghost iconbtn" id="exportNote" aria-label="Download this note">${icon('download')}</button><button class="btn ghost iconbtn" id="deleteNote" aria-label="Delete this note">${icon('trash')}</button></div></div><label for="noteTitle" class="screenreader">Note title</label><input class="editor-title" id="noteTitle" value="${escapeHTML(note.title)}" placeholder="Untitled note" maxlength="150">${preview?`<div class="note-preview">${markdown(note.body)}</div>`:`<label for="noteBody" class="screenreader">Note contents</label><textarea class="editor-body" id="noteBody" placeholder="Start anywhere. Follow a thought…">${escapeHTML(note.body)}</textarea>`}<hr><div class="row between"><small class="muted" id="wordCount">${note.body.trim()?note.body.trim().split(/\s+/).length:0} words</small><small class="muted"># Heading &nbsp; **bold** &nbsp; *italic* &nbsp; - list</small></div>`:'<div class="empty">A blank sky. Create your first note.</div>'}</section></div>`;$('#addNote').onclick=()=>{const id=uid();state.notes.unshift({id,title:'Untitled note',tag:'Ideas',body:'',updatedAt:new Date().toISOString()});selectedNote=id;preview=false;activity('Started a new note');renderLibrary();$('#noteTitle').focus();$('#noteTitle').select();};$('#noteSearch').oninput=e=>{const pos=e.target.selectionStart;noteQuery=e.target.value.toLowerCase();renderLibrary();$('#noteSearch').focus();$('#noteSearch').setSelectionRange(pos,pos);};$$('[data-note]').forEach(b=>b.onclick=()=>{selectedNote=b.dataset.note;renderLibrary();});if(!note)return;$$('[data-editor]').forEach(b=>b.onclick=()=>{preview=b.dataset.editor==='preview';renderLibrary();});const updateNote=()=>{note.title=$('#noteTitle').value;note.tag=$('#noteTag').value;note.body=$('#noteBody')?$('#noteBody').value:note.body;note.updatedAt=new Date().toISOString();save();$('#noteStatus').textContent=storageOK?'Saved on this device':'Export to keep your work';$('#wordCount').textContent=(note.body.trim()?note.body.trim().split(/\s+/).length:0)+' words';const item=$(`[data-note="${note.id}"] strong`);if(item)item.textContent=note.title||'Untitled note';};['noteTitle','noteTag','noteBody'].forEach(id=>{if($('#'+id))$('#'+id).oninput=updateNote;});$('#exportNote').onclick=()=>download(note.title.replace(/[^a-z0-9 -]/gi,'').slice(0,50)+'.md',note.body,'text/markdown');$('#deleteNote').onclick=()=>{modal('Let this thought go?',`<p class="muted">“${escapeHTML(note.title)}” will be deleted. You can download the note first to keep a copy.</p>`,`<div class="modal-actions"><button class="btn" id="keepNote">Keep note</button><button class="btn accent" id="removeNote">Delete note</button></div>`);$('#keepNote').onclick=()=>$('#modal').close();$('#removeNote').onclick=()=>{state.notes=state.notes.filter(n=>n.id!==note.id);save();$('#modal').close();renderLibrary();toast('Note removed.');};};}
function download(name,content,type){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let labFrame,labTime=0,labPaused=false;
const palettes=[['#c9e7a0','#88aa79','#e2bd85'],['#e8b0d4','#9e8bb8','#819acb'],['#f4b57d','#da7865','#e6cc9a'],['#c2e3e2','#6babbb','#e4e6c6']];
function renderLab(){$('#content').innerHTML=head('STRUCTURE MEETS SERENDIPITY','Make a beautiful accident.','An interactive canvas. A few simple controls. Endless possibilities.',`<button class="btn primary" id="exportArt">${icon('download')}Export artwork</button>`)+`<div class="lab-layout"><section class="canvas-wrap"><span class="canvas-label">ORBIT / GENERATIVE STUDY <span id="studyNumber">${String(state.lab.seed).padStart(4,'0')}</span></span><canvas id="artCanvas" aria-label="Animated generative artwork"></canvas><span class="canvas-bottom">PLAY. ADJUST. DISCOVER.</span><button class="btn small" id="pauseArt" style="position:absolute;right:20px;bottom:18px">${icon('pause')}Pause</button></section><aside class="panel lab-controls"><div class="panel-head"><h2>Your ingredients</h2>${icon('lab')}</div><div class="field"><label for="pattern">Pattern</label><select id="pattern">${[['flow','Orbital flow'],['waves','Resonant waves'],['constellation','Constellation'],['bloom','Radial bloom']].map(([v,l])=>`<option value="${v}" ${state.lab.pattern===v?'selected':''}>${l}</option>`).join('')}</select></div>${[['density','Density',20,160],['speed','Movement',0,100],['scale','Expansion',10,100]].map(([id,title,min,max])=>`<div class="field"><label class="range-label" for="${id}">${title}<output id="${id}Value">${state.lab[id]}</output></label><input id="${id}" type="range" min="${min}" max="${max}" value="${state.lab[id]}"></div>`).join('')}<div class="field"><label>Color story</label><div class="swatches">${palettes.map((p,i)=>`<button class="swatch ${i===state.lab.palette?'active':''}" data-palette="${i}" style="--swatch:${p[0]}" aria-label="${['Meadow','Dusk','Ember','Tide'][i]} palette" aria-pressed="${i===state.lab.palette}"></button>`).join('')}</div></div><hr><div class="stack"><button class="btn" id="randomArt">✳ &nbsp; Surprise me</button><button class="btn ghost small" id="saveStudy">${icon('library')}Save study to notebook</button><p class="muted" style="font-size:11px">Every variation is made in your browser. Export a still image of this exact moment.</p></div></aside></div><div class="grid three" style="margin-top:22px">${[['01','Follow the motion','Try a different pattern. Every one has its own rhythm.'],['02','Change one thing','Adjust density or expansion and see how the composition shifts.'],['03','Keep a moment','Pause when it feels right, then export your artwork as a PNG.']].map(([n,t,p])=>`<div class="panel"><span class="eyebrow muted">${n} / FIELD NOTES</span><h3 style="margin:12px 0 8px">${t}</h3><p class="muted" style="font-size:12px">${p}</p></div>`).join('')}</div>`;$('#pattern').onchange=e=>{state.lab.pattern=e.target.value;save();};['density','speed','scale'].forEach(k=>$('#'+k).oninput=e=>{state.lab[k]=Number(e.target.value);$('#'+k+'Value').textContent=e.target.value;save();});$$('[data-palette]').forEach(b=>b.onclick=()=>{state.lab.palette=Number(b.dataset.palette);save();$$('[data-palette]').forEach(s=>{const active=s===b;s.classList.toggle('active',active);s.setAttribute('aria-pressed',active);});});$('#pauseArt').onclick=()=>{labPaused=!labPaused;$('#pauseArt').innerHTML=icon(labPaused?'play':'pause')+(labPaused?'Resume':'Pause');};$('#randomArt').onclick=()=>{state.lab.seed=Math.floor(Math.random()*9999);state.lab.pattern=['flow','waves','constellation','bloom'][Math.floor(Math.random()*4)];state.lab.palette=Math.floor(Math.random()*4);state.lab.scale=20+Math.floor(Math.random()*70);save();cancelAnimationFrame(labFrame);renderLab();};$('#exportArt').onclick=()=>$('#artCanvas').toBlob(blob=>{if(blob){download('orbit-study-'+state.lab.seed+'.png',blob,'image/png');activity('Exported a generative artwork');toast('Your artwork is ready.');}});$('#saveStudy').onclick=()=>{const p=state.lab;state.notes.unshift({id:uid(),title:'Generative study '+p.seed,tag:'Creative',body:`# Study ${p.seed}\n\nPattern: ${p.pattern}\nPalette: ${['Meadow','Dusk','Ember','Tide'][p.palette]}\nDensity: ${p.density}\nMovement: ${p.speed}\nExpansion: ${p.scale}\n\n## What I noticed\n`,updatedAt:new Date().toISOString()});activity('Saved a generative study');toast('Study settings saved to your notebook.');};const canvas=$('#artCanvas');const ctx=canvas.getContext('2d');const resize=()=>{const r=canvas.getBoundingClientRect();const ratio=Math.min(devicePixelRatio||1,2);canvas.width=r.width*ratio;canvas.height=r.height*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);};new ResizeObserver(resize).observe(canvas);resize();let previous=0;function draw(now){const dt=Math.min((now-previous)/1000,.05);previous=now;if(!labPaused&&state.profile.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)labTime+=dt*state.lab.speed/40;const {width:w,height:h}=canvas.getBoundingClientRect();ctx.fillStyle='#162120';ctx.fillRect(0,0,w,h);const p=state.lab;const colors=palettes[p.palette];const cx=w/2,cy=h/2;ctx.strokeStyle='#ffffff08';ctx.lineWidth=1;for(let i=0;i<w;i+=40){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,h);ctx.stroke();}for(let i=0;i<h;i+=40){ctx.beginPath();ctx.moveTo(0,i);ctx.lineTo(w,i);ctx.stroke();}const radius=Math.min(w,h)*(.15+p.scale/220);const pts=[];for(let i=0;i<p.density;i++){const a=i*2.399963+p.seed*.01;const f=i/p.density;let x,y;if(p.pattern==='flow'){const r=radius*Math.sqrt(f);const spin=a+labTime*.13+(1-f)*1.8;x=cx+Math.cos(spin)*r*1.25;y=cy+Math.sin(spin)*r*.82;}else if(p.pattern==='waves'){x=w*.12+f*w*.76;y=cy+Math.sin(f*12+labTime*.7)*radius*.5+Math.cos(f*24-labTime*.3)*radius*.23;}else if(p.pattern==='bloom'){const r=radius*(.5+.5*Math.sin(a*5+labTime*.3));x=cx+Math.cos(a)*r;y=cy+Math.sin(a)*r;}else{x=cx+Math.sin(a+p.seed)*radius*1.3;y=cy+Math.cos(a*1.3+labTime*.07)*radius;}pts.push([x,y]);ctx.fillStyle=colors[i%3];ctx.globalAlpha=.45+.55*f;ctx.beginPath();ctx.arc(x,y,p.pattern==='waves'?2.5:1.5+f*3,0,Math.PI*2);ctx.fill();}ctx.lineWidth=.55;ctx.globalAlpha=.22;for(let i=0;i<pts.length;i++){for(let j=i+1;j<Math.min(i+9,pts.length);j++){const a=pts[i],b=pts[j];if(Math.hypot(a[0]-b[0],a[1]-b[1])<radius*.65){ctx.strokeStyle=colors[i%3];ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke();}}}ctx.globalAlpha=.35;ctx.strokeStyle=colors[0];ctx.beginPath();ctx.arc(cx,cy,radius*1.15,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1;labFrame=requestAnimationFrame(draw);}labFrame=requestAnimationFrame(draw);}
let audioContext,audioNodes=[],soundPlaying=null,timerInterval;
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(Math.floor(s%60)).padStart(2,'0')}`;}
function remaining(){return state.timer.running?Math.max(0,Math.ceil((state.timer.end-Date.now())/1000)):state.timer.remaining;}
function reconcileTimer(){if(state.timer.running&&remaining()===0){const t=state.timer;t.running=false;t.end=null;t.remaining=0;if(t.mode==='focus'){state.sessions.push({id:uid(),minutes:Math.round(t.duration/60),at:new Date().toISOString()});activity('Completed a '+Math.round(t.duration/60)+' minute focus session');}save();toast(t.mode==='focus'?'Session complete. Take a breath.':'Break complete. Ready when you are.');}}
function renderFocus(){reconcileTimer();const t=state.timer;$('#content').innerHTML=head('LESS NOISE. MORE POSSIBILITY.','Give one thing your attention.','A gentle timer and a little atmosphere. The rest can wait.',`<a class="btn" href="planner.html">Choose a project ${icon('arrow')}</a>`)+`<div class="focus-layout"><section class="focus-stage"><div class="segmented">${[['focus','Deep work'],['short','Short break'],['long','Long break']].map(([m,l])=>`<button data-mode="${m}" class="${t.mode===m?'active':''}">${l}</button>`).join('')}</div><div class="timer-ring"><svg viewBox="0 0 285 285" aria-hidden="true"><circle class="track" cx="142.5" cy="142.5" r="138"/><circle class="fill" id="timerProgress" cx="142.5" cy="142.5" r="138"/></svg><div><div class="timer-time" id="timerTime" role="timer" aria-live="off">${formatTime(remaining())}</div><div class="timer-caption" id="timerCaption">${t.running?'IN YOUR ELEMENT':t.remaining===0?'A MOMENT WELL SPENT':'A LITTLE SPACE TO BEGIN'}</div></div></div><div class="row"><button class="btn primary" id="timerToggle">${icon(t.running?'pause':'play')}${t.running?'Pause session':t.remaining===0?'Start again':'Begin session'}</button><button class="btn iconbtn" id="timerReset" aria-label="Reset timer">${icon('reset')}</button></div><div class="row" style="margin-top:25px"><label for="focusMinutes" class="muted" style="font-size:11px">Session length</label><select id="focusMinutes" style="width:100px;font-size:11px;padding:6px" ${t.running?'disabled':''}>${[1,5,15,25,45,60].map(m=>`<option value="${m}" ${Math.round(t.duration/60)===m?'selected':''}>${m} min</option>`).join('')}</select></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>Set the atmosphere</h2><span class="pill">SOUND OFF BY DEFAULT</span></div>${[['rain','Soft rain','A steady wash of calm'],['space','Deep space','A low, warm hum'],['forest','Forest air','A soft breeze through the canopy']].map(([s,t,d])=>`<div class="sound-option"><div><h3 style="font-size:13px">${t}</h3><small>${d}</small></div><button class="btn small" data-sound="${s}" aria-pressed="false" aria-label="Play ${t}">${icon('play')}</button></div>`).join('')}<div class="field" style="margin-top:20px"><label for="volume">Volume</label><input id="volume" type="range" min="0" max="100" value="25"></div><small class="muted">Synthesized ambience. Use headphones for a softer space.</small></section><section class="panel" style="background:var(--lime);color:#354121"><span class="eyebrow">ONE SMALL PRACTICE</span><p class="quote" style="font-size:22px">Before you begin, choose the one thing that would make this time feel worthwhile.</p><span style="font-size:11px">${state.sessions.length} focus sessions completed</span></section></div></div>`;$$('[data-mode]').forEach(b=>b.onclick=()=>{if(state.timer.running){toast('Pause your session before switching modes.');return;}const m=b.dataset.mode;const duration={focus:1500,short:300,long:900}[m];state.timer={mode:m,duration,remaining:duration,running:false,end:null};save();renderFocus();});$('#timerToggle').onclick=()=>{if(t.running){t.remaining=remaining();t.running=false;t.end=null;}else{if(t.remaining===0)t.remaining=t.duration;t.end=Date.now()+t.remaining*1000;t.running=true;}save();updateTimer();};$('#timerReset').onclick=()=>{t.running=false;t.end=null;t.remaining=t.duration;save();updateTimer();};$('#focusMinutes').onchange=e=>{t.duration=Number(e.target.value)*60;t.remaining=t.duration;save();updateTimer();};$$('[data-sound]').forEach(b=>b.onclick=()=>toggleSound(b.dataset.sound));$('#volume').oninput=e=>{if(audioContext&&audioNodes.length)audioNodes.at(-1).gain.setTargetAtTime(Number(e.target.value)/100*.2,audioContext.currentTime,.15);};updateTimer();clearInterval(timerInterval);timerInterval=setInterval(()=>{reconcileTimer();updateTimer();},500);}
function updateTimer(){if(!$('#timerTime'))return;const t=state.timer;$('#timerTime').textContent=formatTime(remaining());$('#timerProgress').style.strokeDashoffset=867*(1-remaining()/t.duration);$('#timerCaption').textContent=t.running?'IN YOUR ELEMENT':t.remaining===0?'A MOMENT WELL SPENT':'A LITTLE SPACE TO BEGIN';$('#timerToggle').innerHTML=icon(t.running?'pause':'play')+(t.running?'Pause session':t.remaining===0?'Start again':'Begin session');$('#focusMinutes').disabled=t.running;}
async function toggleSound(sound){audioNodes.forEach(n=>{try{if(n.stop)n.stop();n.disconnect();}catch{}});audioNodes=[];if(soundPlaying===sound){soundPlaying=null;}else{try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();await audioContext.resume();const gain=audioContext.createGain();gain.gain.value=Number($('#volume').value)/100*.2;gain.connect(audioContext.destination);if(sound==='space'){const osc=audioContext.createOscillator();osc.type='sine';osc.frequency.value=110;osc.connect(gain);osc.start();audioNodes.push(osc);}else{const buffer=audioContext.createBuffer(1,audioContext.sampleRate*3,audioContext.sampleRate);const data=buffer.getChannelData(0);let brown=0;for(let i=0;i<data.length;i++){brown=(brown+Math.random()*.04-.02)/1.02;data[i]=sound==='rain'?Math.random()*2-1:brown*6;}const source=audioContext.createBufferSource();source.buffer=buffer;source.loop=true;const filter=audioContext.createBiquadFilter();filter.type='lowpass';filter.frequency.value=sound==='rain'?1400:500;source.connect(filter);filter.connect(gain);source.start();audioNodes.push(source,filter);}audioNodes.push(gain);soundPlaying=sound;}catch{toast('Audio is unavailable in this browser.');soundPlaying=null;}}$$('[data-sound]').forEach(b=>{const active=b.dataset.sound===soundPlaying;b.innerHTML=icon(active?'pause':'play');b.setAttribute('aria-pressed',active);b.setAttribute('aria-label',(active?'Stop ':'Play ')+b.dataset.sound+' ambience');});}
function renderInsights(){const done=state.tasks.filter(t=>t.status==='done'),minutes=state.sessions.reduce((a,s)=>a+s.minutes,0);const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return d;});const perDay=days.map(d=>state.sessions.filter(s=>new Date(s.at).toDateString()===d.toDateString()).reduce((a,s)=>a+s.minutes,0));const max=Math.max(...perDay,30);const pct=state.tasks.length?Math.round(done.length/state.tasks.length*100):0;$('#content').innerHTML=head('A LITTLE EVIDENCE OF PROGRESS','Your momentum, made visible.','Every small step counts. These numbers come from your workspace.',`<button class="btn" id="exportInsights">${icon('download')}Export activity</button>`)+`<div class="grid four" style="margin-bottom:22px">${[['Focus minutes',minutes,'Completed sessions only'],['Projects landed',done.length,'On your current board'],['Ideas captured',state.notes.length,'Notes in your collection'],['Worlds collected',state.saved.length,'Creative sparks saved']].map(([l,v,s])=>`<div class="panel stat"><span class="eyebrow muted">${l}</span><div class="number">${v}</div><small class="muted">${s}</small></div>`).join('')}</div><div class="grid two"><section class="panel"><div class="panel-head"><h2>Space for deep work</h2><span class="pill">LAST 7 DAYS</span></div><svg class="chart" viewBox="0 0 560 240" role="img" aria-label="Focus minutes over seven days: ${perDay.join(', ')}"><g stroke="var(--line)" stroke-dasharray="3 5">${[40,100,160,200].map(y=>`<path d="M35 ${y}H545"/>`).join('')}</g><text x="0" y="45">${max}</text><text x="5" y="205">0</text>${perDay.map((v,i)=>{const x=50+i*70,h=v/max*155;return `<rect x="${x}" y="${200-h}" width="35" height="${Math.max(h,2)}" rx="5" fill="${v?'var(--lime)':'var(--line)'}"/><text x="${x+17}" y="${190-h}" text-anchor="middle">${v}</text><text x="${x+17}" y="225" text-anchor="middle">${days[i].toLocaleDateString(undefined,{weekday:'short'})}</text>`;}).join('')}</svg>${minutes===0?'<p class="muted" style="font-size:12px">Your first completed focus session will bring this chart to life. <a class="learn-link" href="focus.html">Make a little space ↗</a></p>':''}</section><section class="panel"><div class="panel-head"><h2>Ideas into action</h2>${icon('planner')}</div><div class="row" style="margin:30px 0"><svg viewBox="0 0 120 120" style="width:150px;flex-shrink:0" role="img" aria-label="${pct}% projects completed"><circle cx="60" cy="60" r="49" fill="none" stroke="var(--soft)" stroke-width="13"/><circle cx="60" cy="60" r="49" fill="none" stroke="var(--accent)" stroke-width="13" stroke-dasharray="${pct/100*308} 308" transform="rotate(-90 60 60)"/><text x="60" y="65" text-anchor="middle" fill="var(--ink)" font-size="23">${pct}%</text></svg><div class="stack">${[['todo','On the horizon'],['active','In orbit'],['done','Landed']].map(([s,l])=>`<div class="row between"><span class="muted" style="font-size:12px">${l}</span><strong>${state.tasks.filter(t=>t.status===s).length}</strong></div>`).join('')}</div></div><p class="muted" style="font-size:12px">Progress has its own pace. A project is counted when you move it to Landed.</p></section></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Your quiet consistency</h2><span class="eyebrow muted">THE LAST 91 DAYS</span></div><p class="muted" style="font-size:12px">Completed focus sessions and projects, one day at a time.</p><div class="heatmap">${Array.from({length:91},(_,i)=>{const d=new Date();d.setDate(d.getDate()-90+i);const count=state.sessions.filter(s=>new Date(s.at).toDateString()===d.toDateString()).length+done.filter(t=>t.completedAt&&new Date(t.completedAt).toDateString()===d.toDateString()).length;return `<div class="heat-cell level${Math.min(3,count)}" role="img" aria-label="${d.toLocaleDateString()}: ${count} completed actions" title="${d.toLocaleDateString()}: ${count} completed actions"></div>`;}).join('')}</div><div class="row" style="justify-content:flex-end;margin-top:15px"><small class="muted">Less</small>${[0,1,2,3].map(l=>`<span class="heat-cell level${l}" style="width:12px;height:12px"></span>`).join('')}<small class="muted">More</small></div></section>`;$('#exportInsights').onclick=()=>{const rows=[['type','title','minutes','date'],...state.sessions.map(s=>['focus','Focus session',s.minutes,s.at]),...done.map(t=>['project',t.title,'',t.completedAt||''])];download('orbit-activity.csv',rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv');};}
function renderSettings(){$('#content').innerHTML=head('A SPACE THAT FEELS LIKE YOU','Make yourself at home.','A few small adjustments to bring your workspace into your orbit.')+`<div class="settings-layout"><div class="stack"><section class="panel"><div class="panel-head"><h2>Your corner of the universe</h2>${icon('home')}</div><form id="profileForm"><div class="field"><label for="profileName">What should we call you?</label><input id="profileName" value="${escapeHTML(state.profile.name)}" required maxlength="30" placeholder="Your name"></div><button class="btn primary" type="submit">Save your name</button></form><hr><div class="field"><label>Appearance</label><div class="row">${['light','dark'].map(t=>`<button class="theme-card ${state.profile.theme===t?'active':''}" data-themechoice="${t}" aria-pressed="${state.profile.theme===t}"><div class="theme-preview ${t}"></div>${t==='light'?'Daylight':'After hours'}</button>`).join('')}</div></div><div class="setting-row"><div><strong style="font-size:13px">Gentle motion</strong><p>Animated artwork and orbital illustrations</p></div><button class="toggle" id="motionToggle" role="switch" aria-label="Gentle motion" aria-checked="${state.profile.motion}"></button></div></section><section class="panel"><div class="panel-head"><h2>Find your way faster</h2><span class="key">Ctrl K</span></div><div class="setting-row"><span>Open workspace search</span><span class="key">Ctrl / ⌘ K</span></div><div class="setting-row"><span>Close a dialog</span><span class="key">Esc</span></div><div class="setting-row"><span>Move between controls</span><span class="key">Tab</span></div><p class="muted" style="font-size:11px;margin-top:16px">All project statuses can be changed without dragging. Your system’s reduced motion preference is respected.</p></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2>Your work stays yours</h2>${icon('library')}</div><p class="muted" style="font-size:12px">Projects, notes, collections, and focus sessions are saved in this browser. They are not synced between devices. Clearing browser data can remove them.</p><div class="setting-row"><div><strong style="font-size:13px">Export a backup</strong><p>Keep a portable copy of your full workspace</p></div><button class="btn small" id="exportData">${icon('download')}Export</button></div><div class="setting-row"><div><strong style="font-size:13px">Restore a backup</strong><p>Replace this workspace with an ORBIT backup</p></div><button class="btn small" id="importData">Import</button><input id="importFile" type="file" accept=".json,application/json" hidden></div><div class="setting-row"><div><strong style="font-size:13px">A fresh start</strong><p>Clear your work and restore the starter content</p></div><button class="btn small" id="resetData">Reset</button></div><div class="info-strip" style="margin-top:20px">${icon('info')}Local storage: ${storageOK?'available':'unavailable'}. Export regularly to keep a copy.</div></section><section class="panel" style="background:var(--purple);color:#453452"><span class="eyebrow">THE ORBIT PHILOSOPHY</span><p class="quote">Useful enough for every day.<br>Curious enough for what’s next.</p><p style="font-size:12px">An independent little universe. No accounts, no feeds, no busywork. Just the room to make things happen.</p><button class="btn" id="showIntro" style="margin-top:20px">Take the quick tour ${icon('arrow')}</button></section></div></div>`;$('#profileForm').onsubmit=e=>{e.preventDefault();const name=$('#profileName').value.trim();if(!name){$('#profileName').setCustomValidity('Enter a name to use in your workspace.');$('#profileName').reportValidity();return;}state.profile.name=name;save();$$('.avatar').forEach(a=>a.textContent=name.slice(0,2).toUpperCase());toast('A little more you. Name updated.');};$('#profileName').oninput=e=>e.target.setCustomValidity('');$$('[data-themechoice]').forEach(b=>b.onclick=()=>{state.profile.theme=b.dataset.themechoice;applyPreferences();save();renderSettings();});$('#motionToggle').onclick=()=>{state.profile.motion=!state.profile.motion;applyPreferences();save();$('#motionToggle').setAttribute('aria-checked',state.profile.motion);};$('#exportData').onclick=()=>{download('orbit-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');toast('Your workspace backup is ready.');};$('#importData').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('Please choose a backup smaller than 5 MB.');const data=JSON.parse(await file.text());validateBackup(data);modal('Restore this workspace?',`<p class="muted">This backup has ${data.tasks.length} projects and ${data.notes.length} notes. It will replace your current workspace. Export your current work first if you want to keep it.</p>`,`<div class="modal-actions"><button class="btn" id="cancelImport">Cancel</button><button class="btn primary" id="confirmImport">Restore backup</button></div>`);$('#cancelImport').onclick=()=>$('#modal').close();$('#confirmImport').onclick=()=>{state=data;state.timer.running=false;state.timer.end=null;save();location.reload();};}catch(err){toast(err.message||'This is not a valid ORBIT backup.');}e.target.value='';};$('#resetData').onclick=()=>{modal('Begin a new orbit?',`<p class="muted">This removes your projects, notes, collections, and sessions from this browser. Export a backup first if you want to keep them.</p>`,`<div class="modal-actions"><button class="btn" id="cancelReset">Keep my workspace</button><button class="btn accent" id="confirmReset">Reset workspace</button></div>`);$('#cancelReset').onclick=()=>$('#modal').close();$('#confirmReset').onclick=()=>{state=initial();state.onboarded=true;save();location.reload();};};$('#showIntro').onclick=showWelcome;}
function validateBackup(d){const fail=()=>{throw Error('This file is not a valid ORBIT workspace backup.');};const str=(x,max=100000)=>typeof x==='string'&&x.length<=max;const iso=x=>str(x)&&!Number.isNaN(Date.parse(x));const finite=x=>typeof x==='number'&&Number.isFinite(x);const ids=new Set();if(!d||d.version!==1||!d.profile||!str(d.profile.name,30)||!d.profile.name.trim()||!['light','dark'].includes(d.profile.theme)||typeof d.profile.motion!=='boolean')fail();if(!Array.isArray(d.tasks)||d.tasks.length>5000||!d.tasks.every(t=>{if(!t||!str(t.id,100)||!/^[a-zA-Z0-9_-]+$/.test(t.id)||ids.has(t.id))return false;ids.add(t.id);return str(t.title,120)&&str(t.description,1500)&&['Creative','Discovery','Personal'].includes(t.category)&&['Low','Normal','High'].includes(t.priority)&&['todo','active','done'].includes(t.status)&&str(t.date,10)&&(!t.date||/^\d{4}-\d{2}-\d{2}$/.test(t.date))&&(!t.completedAt||iso(t.completedAt));}))fail();if(!Array.isArray(d.notes)||d.notes.length>5000||!d.notes.every(n=>{if(!n||!str(n.id,100)||!/^[a-zA-Z0-9_-]+$/.test(n.id)||ids.has(n.id))return false;ids.add(n.id);return str(n.title,150)&&str(n.tag,30)&&str(n.body,500000)&&iso(n.updatedAt);}))fail();if(!Array.isArray(d.saved)||!d.saved.every(id=>destinations.some(x=>x.id===id))||!Array.isArray(d.sessions)||!d.sessions.every(s=>s&&str(s.id,100)&&finite(s.minutes)&&s.minutes>0&&s.minutes<=60&&iso(s.at))||!Array.isArray(d.activity)||!d.activity.every(a=>a&&str(a.text,500)&&iso(a.time)))fail();const t=d.timer,l=d.lab;if(!t||!['focus','short','long'].includes(t.mode)||!finite(t.duration)||t.duration<60||t.duration>3600||!finite(t.remaining)||t.remaining<0||t.remaining>t.duration||typeof t.running!=='boolean'||(t.running&&!finite(t.end)))fail();if(!l||!['flow','waves','constellation','bloom'].includes(l.pattern)||![l.density,l.speed,l.scale,l.seed,l.palette].every(finite)||l.density<20||l.density>160||l.speed<0||l.speed>100||l.scale<10||l.scale>100||!Number.isInteger(l.palette)||l.palette<0||l.palette>3)fail();}
shell();
({home:renderHome,planner:renderPlanner,atlas:renderAtlas,library:renderLibrary,lab:renderLab,focus:renderFocus,insights:renderInsights,settings:renderSettings}[page]||renderHome)();
if(page==='planner'){const id=new URLSearchParams(location.search).get('task');if(state.tasks.some(t=>t.id===id))editTask(id);}
if(!state.onboarded&&page==='home'){state.onboarded=true;save();setTimeout(showWelcome,750);}
window.addEventListener('pagehide',()=>{cancelAnimationFrame(labFrame);clearInterval(timerInterval);save();if(audioContext)audioContext.close();});

